INSERT INTO "entities" VALUES('ent_de013687d92d492592c2a4e0aa3f5a4c','Signing in.','2026-10-22T18:38:42.170Z',NULL,NULL,NULL);
INSERT INTO "entities" VALUES('ent_e6683a04c6a54dec84e8966cd3a8db0a','An authenticated visit.','2026-10-22T18:38:42.181Z',NULL,NULL,NULL);
INSERT INTO "entity_link_type_glossary" VALUES('contains','Parent → member. Structural composition between long-lived entities (e.g. parent corp → subsidiary, category → member). Same top-down direction as statement links: parent is the source.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "entity_link_type_glossary" VALUES('replaces','Source entity supersedes target entity (e.g. one provider replacing another).','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "entity_link_type_glossary" VALUES('sub-type','Source is a specialization of target. Reads ''source is a sub-type of target'' (e.g. Ubeeo is a sub-type of ATS, hard_skill_german_language is a sub-type of Hard Skill). Parent / general category at the target end.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "entity_link_type_glossary" VALUES('has','Source has the target as a component, attribute, or related object. Generic ownership/composition relation between long-lived entities when neither `contains` (strict structural membership) nor `sub-type` (specialization) fits.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "entity_link_type_glossary" VALUES('uses','Source depends on or makes use of target. Behavioural dependency between long-lived entities — distinct from structural composition (`contains`) and specialization (`sub-type`).','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "entity_links" VALUES('ent_de013687d92d492592c2a4e0aa3f5a4c','ent_e6683a04c6a54dec84e8966cd3a8db0a','contains','2026-10-22T18:38:42.183Z',NULL);
