INSERT INTO "pending_mentions" VALUES(2,'stm_30ad9900628c41c5b2f06fcf67f10a1c','nam_25423718608542868f51b9d9f985606d','2026-08-01','2026-08-01','curator',NULL,NULL);
INSERT INTO "statement_kind_glossary" VALUES('event','Something happening — an atomic occurrence in the product (creation, submission, rejection, dispatch).','Discrete things that fire, succeed, or are rejected. Use action-as-subject phrasing (''an invite is submitted''), with the actor in `mentions` unless the actor''s identity is itself the claim (in which case use `capability`).','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_kind_glossary" VALUES('state','A genuinely persisting, observable condition of a named entity — enum values, configuration flags, or conditions at a decision point.','Enum/status values (''Applied'' on Draft Status), config flags (''Auto result sharing enabled'' on Company), or observable missing-input conditions (''No name on the invite'' on Invite). Often referenced as `when` leaves on conditional edges. Do NOT use for derived/computed conditions or internal-mechanism steps.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_kind_glossary" VALUES('capability','A modal claim about what is possible — ''X can do Y''. Warranted only when the actor''s identity or permission boundary is itself the claim, or when it anchors a `governed-by` rule tree.','Authoring an event already implies the action is possible. Reach for `capability` when the point of the statement is who is allowed, what is gated, or which rule decomposition this modal anchors. Otherwise prefer `event`.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_kind_glossary" VALUES('rule','A deterministic, non-contingent claim — formula, default, enumeration, or bound that holds the same way across all instances and moments.','Definitional or computational claims (''statement kind is one of: event, state, capability, rule, property''; ''rank score equals similarity contribution plus recency boost minus staleness penalty''). Apply the contingency test: if the same claim could be otherwise for a specific entity or at a specific time, it is a `state`, not a `rule`.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_kind_glossary" VALUES('property','A slot on an entity that holds a value — short noun-phrase label, not a sentence. ''Email'', ''Server host'', ''Similarity score''.','When the meaningful question is *what value* rather than *does this hold*. User-supplied configuration values, user-supplied event inputs, or derived/computed values. Anchored to its entity via `mentions`. Reach for this instead of packing inputs into event text.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_kind_glossary" VALUES('procedure','The named root of a how-to guide. ''How to connect an MCP client to a Mycelium server.'' Composes `action`s, `property` inputs, and optional `check`s into a runnable script.','Authoring prescriptive content: a guide the user (or an agent) executes to accomplish something. Anchors to a `capability` via `teaches`. The body is composed via `contains` / `next` to actions, and `requires` / `accepts` to property inputs.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_kind_glossary" VALUES('action','A step the user performs that modifies the system. ''Click the Save button.'' Anchors to a descriptive `event` via `performs`.','Single UI interactions inside a procedure or diagnostic flow: clicks, navigations, entries, sends. Each action is its own statement; the procedure `contains` them or chains them via `next`.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_kind_glossary" VALUES('check','A verification step for a diagnostic agent — observing the system without changing it. ''Verify the user''s authentication provider matches the login method.''','Diagnostic flows where a step inspects rather than mutates. Anchors to a `state` via `verifies`. Branches with `on-success` / `on-failure` or links to a `cause` via `confirms` / `refutes`.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_kind_glossary" VALUES('cause','A named failure mode worth investigating. ''User is attempting password login on a social-only account.''','Roots of a diagnostic tree. Optionally anchors to a `state` via `violates` when the failure mode is ''a required state isn''t met''. Free-standing when the failure is environmental, historical, referential, or compound.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('contains','Sub-step inside the same process. Target only makes sense as part of the parent (e.g. ''The write pipeline executes'' contains ''The extraction agent runs'').','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('triggers','A *separate* downstream process fires as a consequence. Target stands on its own clock (e.g. ''An invite is created'' triggers ''A notification email is sent'').','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('establishes','Source produces a resulting state. Multiple statements can each `establishes` the same state — the state becomes the convergence point. No intermediate events: if event A causes state S, link A → establishes → S directly; do not create an intermediate event whose only purpose is to establish S.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('enables','Source unlocks target''s capability without directly invoking it (e.g. ''Embeddings are generated'' enables ''Vector search returns ranked results''). Do NOT use for condition states — a state referenced in a `when` expression on an edge must not also have an `enables` link to the same target.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('requires','Two uses: (1) target must hold for source to fire, usually paired with a `when` clause when the prerequisite is itself a statement; (2) source consumes the target `property` as a mandatory input in this context.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('accepts','Source consumes the target `property` as an *optional* input in this context. The same property record is referenced from a `requires` edge elsewhere — optionality is per-edge, not per-property.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('varies-by','Source''s behavior depends on target as a parameter — shapes *how* source plays out, not *whether* it fires.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('configures','Source parameterises target before target fires. Use sparingly; `contains` is often cleaner.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('replaces','Source supersedes target. Almost always with a `when` clause — ''replaces under condition C''.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('restricts','Source limits target''s operation. Use when the limit is itself a *statement* (a kill-switch, a feature flag).','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('proceeds','Sequential hand-off in the same flow. A proceeds to B means B is the immediate next step after A in a continuous sequence — neither a contained sub-step (`contains`) nor an independently-fired downstream process (`triggers`). Use when A''s completion naturally flows into B without a causal gap.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('fallback-to','Ordered priority chain. A fallback-to B means B applies only when A does not. Forms a linear chain; first applicable option wins. Distinct from `cases` (enumeration over a named value set) and `composes` (grouping without ordering).','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('governed-by','The rule that determines how a capability works. Typically: capability → governed-by → top-level rule.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('composes','Sub-formula or sub-rule; together the composed statements specify the parent. Carry `when`-conditions on these edges for conditional applicability. Not the same as `cases`.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('cases','Enumerated branches over a named, finite value set only (statement kinds, link types, etc.). Each edge points to one branch. Do NOT use for continuous predicates — use a `when`-condition on a `composes` edge instead.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('valued-by','The source statement''s value is derived by the target rule. Typically: state → valued-by → rule. Do NOT use when the value is configured or input directly.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('supersedes','Versioning: source replaces target.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('teaches','Procedure → capability. Anchors a how-to guide to the capability it teaches the user to exercise. Every `procedure` should `teaches` exactly one capability.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('performs','Action → event. The user step models this product event — the descriptive thing that actually happens when the user performs the step. Anchors the prescriptive action to the descriptive layer.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('verifies','Check → state. The diagnostic check inspects whether this state currently holds, without changing the system. Anchors the check to the descriptive condition being observed.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('violates','Cause → state. The failure mode corresponds to a required state not holding. Optional anchor: a cause may also be free-standing (environmental, historical, referential, or compound) and need no `violates` link.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('obtained-by','Property → action or procedure. How the user finds or produces this value. Empty for values the user types directly or for derived/computed values.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('next','Linear sequence between prescriptive steps. A `next` B means B follows A. Use for action→action and check→check chains. Distinct from descriptive `proceeds` (which connects events).','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('on-success','Branch after a check or action on its success path. Source''s success outcome leads to target. Pair with `on-failure` for the complementary branch.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('on-failure','Branch after a check or action on its failure path. Source''s failure outcome leads to target. Pair with `on-success` for the complementary branch.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('confirms','Check → cause. If this check passes, this cause is the issue. Used in diagnostic trees to link verification steps to the failure modes they identify.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('refutes','Check → cause. If this check passes, this cause is *not* the issue. Used in diagnostic trees to rule causes out.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
INSERT INTO "statement_link_type_glossary" VALUES('resolves','Action → cause. This action fixes the situation when the cause applies. Used to attach remediation steps to diagnosed failure modes.','2026-10-22T18:38:42.041Z',NULL,NULL,NULL);
